shellCommands.command:
/bin/bash -lc "cat <<'EOF' > app/lib/notifications.ts
let notificationEnabled = false;

export async function getNotificationPreference() {
  return notificationEnabled;
}

export async function toggleNotificationPreference() {
  notificationEnabled = "'!notificationEnabled;
  return notificationEnabled;
}
EOF'

/bin/bash -lc "cat <<'EOF' > app/actions.ts
\"use server\";

import { revalidatePath } from \"next/cache\";
import { toggleNotificationPreference } from \"./lib/notifications\";

export async function toggleNotificationAction() {
  await toggleNotificationPreference();
  revalidatePath(\"/\");
}
EOF"
